def fix_spaces(text):
    result = []
    last_was_space = False
    last_was_long_space = False
    space_count = 0

    for char in text:
        if char == ' ':
            if last_was_long_space:
                continue
            elif last_was_space:
                space_count += 1
                if space_count == 2:
                    result[-1] = '-'
                    last_was_long_space = True
            else:
                result.append('_')
                last_was_space = True
                space_count = 1
        else:
            result.append(char)
            last_was_space = False
            last_was_long_space = False

    return ''.join(result)
